<?php
require_once __DIR__ . '/includes/auth.php'; require_login();$pdo=db();$items=$pdo->query('SELECT * FROM announcements WHERE is_published=1 ORDER BY published_at DESC')->fetchAll();$pageTitle='Announcements';$activePage='announcements';require __DIR__.'/partials/header.php';
?><section class="section-heading"><div><div class="eyebrow"><?= current_user()['role']==='resident'?'Resident portal / Community desk':'Community / Information desk' ?></div><h1>Barangay announcements</h1><p>Stay updated with the latest schedules, advisories, and public-service information.</p></div><?php if(current_user()['role']!=='resident'): ?><a class="primary-button" href="announcements.php">＋ New announcement</a><?php endif; ?></section><div class="announcement-card-grid"><?php foreach($items as $item): ?><article class="panel announcement-card"><div class="announcement-banner <?= h(strtolower($item['category'])) ?>"><span><?= h($item['category']) ?></span><small><?= h(date('M d, Y',strtotime($item['published_at']))) ?></small></div><div class="announcement-card-body"><div class="eyebrow">Published update</div><h3><?= h($item['title']) ?></h3><p><?= h($item['body']) ?></p><?php if(current_user()['role']==='resident'): ?><span class="muted">Official barangay information</span><?php endif; ?></div></article><?php endforeach; ?><?php if(!$items): ?><p class="empty-state">No published announcements yet.</p><?php endif; ?></div><?php require __DIR__.'/partials/footer.php'; ?>
